import ShoppingItem from "./ShoppingItem";

function ShoppingItemList({ items, handleDelete }) {
  if (!items || items.length === 0) {
    return <p>Your shopping list is empty</p>;
  }
  console.log(items);
  return (
    <ul className="items">
      {items.map((item) => (
        <ShoppingItem key={item.id} item={item} handleDelete={handleDelete} />
      ))}
    </ul>
  );
}

export default ShoppingItemList;
